// 构建期 sharp 惰性解析 shim（esbuild --alias:sharp 映射到此文件，bundle 内联）。
//
// 背景：dsh-community-market 原样 `import sharp from 'sharp'`（上游在 yarn
// workspace 单树里解析）。DSH Desktop 的部署形态里，市场的原生依赖不随
// profile 逐份分发——sharp 的平台二进制（@img/*）随桌面运行时走（app
// node_modules / 全局 dsh 嵌套树），与 dsh-hub 携带嵌套 node_modules 的
// 纯 JS 依赖不同，28MB 的平台二进制不值得每 profile 复制一份。
//
// 因此把模块顶部的静态导入换成调用期解析：
//   1) 常规解析（本包嵌套 node_modules / profile vendor 同步命中时直接用）；
//   2) 锚定启动本 host 的 dsh CLI 入口（process.argv[1] 的 bin 所在包的
//      node_modules 同级即运行时 sharp——与桥接插件 dshArgv 重入同一锚点）。
// 任一命中即缓存。都未命中时抛在「单张图标规整」调用点——市场浏览/安装
// 不受影响，绝不让整个插件在加载期崩溃（多平台分发下 @img 缺失时优雅降级）。
import { createRequire } from 'node:module';
import { dirname, join, resolve } from 'node:path';

let cached;

function loadSharp() {
  if (cached !== undefined) return cached;
  const attempts = [() => createRequire(import.meta.url)('sharp')];
  const entry = process.argv[1];
  if (typeof entry === 'string' && entry !== '') {
    attempts.push(() => createRequire(join(dirname(resolve(entry)), 'package.json'))('sharp'));
  }
  let lastError;
  for (const attempt of attempts) {
    try {
      cached = attempt();
      return cached;
    } catch (cause) {
      lastError = cause;
    }
  }
  throw lastError ?? new Error('sharp is not available in this desktop runtime');
}

export default function sharp(input, options) {
  return loadSharp()(input, options);
}
